import React from 'react';
import { IStockDetails } from '../../../core/Interface/stockDetailReport.interface';
import { ColumnDef } from '@tanstack/react-table';
import { useTranslation } from 'react-i18next';
import { Box } from '@mui/material';
import { appColors } from '../../../theme/appColors';

const useStockAdjustReportColumns = (
  pageIndex: number,
  pageSize: number,
) => {
  const { t } = useTranslation(['stockAdjust']);

  return [
    {
      accessorKey: 'sn',
      header: <div style={{ textAlign: 'justify' }}>#</div>,
      size: 50,
      cell: (cell) => {
        const serialNumber = pageIndex * pageSize + cell.row.index + 1;
        return <Box sx={{ textAlign: 'justify' }}>{serialNumber}</Box>;
      },
    },
    {
      accessorKey: 'productCode',
      header: t('stockAdjust:productCode'),
      size: 180,
    },
    {
      accessorKey: 'productName',
      header: t('stockAdjust:productName'),
      size: 200,
    },
    {
      accessorKey: 'previousStock',
      header: () => (
        <Box sx={{ textAlign: 'center' }}>{t('stockAdjust:previousStock')}</Box>
      ),
      cell: (cell) => {
        return (
          <Box
            sx={{
              textAlign: 'center',
              fontWeight: 'bold',
              color:
                cell.row.original.previousStock < 0
                  ? appColors.carmineRed[120]
                  : appColors.darkGreen[40],
            }}
          >
            {cell.row.original.previousStock}
          </Box>
        );
      },
      size: 100,
    },
    {
      accessorKey: 'currentStock',
      header: () => (
        <Box sx={{ textAlign: 'center' }}>{t('stockAdjust:currentStock')}</Box>
      ),
      cell: (cell) => {
        return (
          <Box
            sx={{
              textAlign: 'center',
              fontWeight: 'bold',
              color:
                cell.row.original.currentStock < 0
                  ? appColors.carmineRed[120]
                  : appColors.darkGreen[40],
            }}
          >
            {cell.row.original.currentStock}
          </Box>
        );
      },
      size: 100,
    },
    {
      accessorKey: 'remark',
      header: t('stockAdjust:remark'),
      size: 180,
    },
    {
      accessorKey: 'id',
    },
  ] as ColumnDef<IStockDetails>[];
};

export default useStockAdjustReportColumns;
